<script setup lang="ts">
import {ref,watch} from 'vue'
const props=defineProps<{title:string;outro:string;index:number;total:number;videoUrl:string;image:string;clues:string[];shots:Record<string,any>[];replaying:boolean}>()
defineEmits<{continue:[]}>()
const video=ref<HTMLVideoElement|null>(null),playing=ref(false),ended=ref(false)
watch(()=>props.videoUrl,()=>{playing.value=false;ended.value=false})
async function play(){try{await video.value?.play()}catch{playing.value=false}}
</script>

<template>
 <section class="scene-cinema" aria-label="本幕分镜视频">
  <div class="cinema-heading"><span>第 {{String(index+1).padStart(2,'0')}} 幕 · 线索已集齐</span><span>{{index+1}} / {{total}}</span></div>
  <div class="cinema-layout">
   <div class="cinema-screen">
    <template v-if="videoUrl"><video ref="video" :key="videoUrl" :src="videoUrl" controls playsinline preload="auto" @play="playing=true;ended=false" @ended="ended=true;playing=false"/><button v-if="!playing&&!ended" class="cinema-play" @click="play" aria-label="播放本幕分镜视频"><span aria-hidden="true">▶</span><b>观看本幕影像</b><small>让刚才听到的话，成为眼前的一幕</small></button><button v-if="ended" class="cinema-replay" @click="play">↻ 再看一遍</button></template>
    <template v-else><img :src="image" alt="本幕故事的原画参考"><div class="cinema-no-film"><span>这一幕，先留在画中。</span><p>视频尚未选定，你仍可带着线索继续故事。</p></div></template>
   </div>
   <aside class="cinema-notes"><small>{{videoUrl?'本幕分镜 · 已解锁':'本幕故事 · 已解锁'}}</small><h2>{{title}}</h2><p class="cinema-transition">{{outro}}</p><div class="cinema-clues"><span>带走这幕的线索</span><p v-for="(clue,i) in [...new Set(clues)]" :key="i"><i aria-hidden="true">·</i>{{clue}}</p></div><details v-if="!videoUrl&&shots.length"><summary>阅读本幕分镜</summary><p v-for="(shot,i) in shots" :key="i">镜头 {{i+1}} · {{shot.action}}</p></details><button class="cinema-next" @click="$emit('continue')">{{replaying?'返回原来的故事':index===total-1?'合卷，回望此事':'随引路人，继续故事'}} <span aria-hidden="true">→</span></button><span class="cinema-save-note">这一幕已收进线索手记，可随时回看</span></aside>
  </div>
 </section>
</template>

